#include <zephyr/kernel.h>
#include <zephyr/sys/byteorder.h>
#include <zephyr/net_buf.h>
#include <zephyr/mgmt/mcumgr/mgmt/mgmt.h>
#include <zephyr/mgmt/mcumgr/smp/smp.h>
#include <zephyr/mgmt/mcumgr/smp/smp_client.h>
#include <zephyr/mgmt/mcumgr/transport/smp.h>
#include <zephyr/logging/log.h>
#include <mgmt/mcumgr/transport/smp_internal.h>

LOG_MODULE_REGISTER(mcumgr_smp_client, CONFIG_MCUMGR_SMP_CLIENT_LOG_LEVEL);

struct smp_client_cmd_entry {
	struct net_buf *nb;
	smp_client_res_fn cb;
	void *user_data;
	int64_t timeout;
};

struct smp_client_data {
	struct smp_client_cmd_entry cmd_list[CONFIG_MCUMGR_SMP_CLIENT_MAX_CONCURRENT_REQUEST];
	struct k_work_delayable cmd_timeout_work;
	struct k_mutex lock;
	uint8_t smp_seq;
};

static struct smp_client_data client_data;

static void smp_client_handle_Timer(struct k_work *work);

static struct smp_transport *smp_client_transport_get(int smpt_type)
{
	Z_STRUCT_SECTION_FOREACH(smp_client_transport_entry, entry) {
		if (entry->smpt->functions.query_valid_check == NULL) {
			if (entry->smpt_type == smpt_type) {
				return entry->smpt;
			}
		} else {
			if (entry->smpt->functions.query_valid_check(smpt_type)) {
				return entry->smpt;
			}
		}
	}

	return NULL;
}

struct net_buf *smp_client_buf_allocation(struct smp_client_object *smp_client, uint16_t group,
					  uint8_t command_id, uint8_t op, enum smp_mcumgr_version_t version)
{
	struct net_buf *nb;
	struct smp_hdr *uhdr;

	if (op != MGMT_OP_READ && op != MGMT_OP_WRITE) {
		return NULL;
	}

	/* Clear the buffer and allocate from transport pool */
	nb = smp_packet_alloc();
	if (!nb) {
		return NULL;
	}

	uhdr = net_buf_add(nb, sizeof(*uhdr));
	uhdr->nh_op = op;
	uhdr->nh_flags = 0;
	uhdr->nh_len = 0;
	uhdr->nh_group = sys_cpu_to_be16(group);
	uhdr->nh_seq = 0;
	uhdr->nh_id = command_id;
	uhdr->nh_version = version;

	return nb;
}

void smp_client_buf_free(struct net_buf *nb)
{
	smp_packet_free(nb);
}

int smp_client_object_init(struct smp_client_object *smp_client, int smp_type)
{
	smp_client->smpt = smp_client_transport_get(smp_type);
	if (smp_client->smpt) {
		smp_client->priv_data = &client_data;
		return MGMT_ERR_EOK;
	}

	return MGMT_ERR_ENOENT;
}

static void smp_client_timeout_reschedule(void)
{
	int64_t min_timeout = INT64_MAX;
	int64_t current_time = k_uptime_get();

	for (int i = 0; i < CONFIG_MCUMGR_SMP_CLIENT_MAX_CONCURRENT_REQUEST; i++) {
		if (client_data.cmd_list[i].nb) {
			if (client_data.cmd_list[i].timeout < min_timeout) {
				min_timeout = client_data.cmd_list[i].timeout;
			}
		}
	}

	if (min_timeout == INT64_MAX) {
		k_work_cancel_delayable(&client_data.cmd_timeout_work);
		return;
	}

	if (min_timeout <= current_time) {
		/* Trigger timeout handling immediately */
		k_work_reschedule(&client_data.cmd_timeout_work, K_NO_WAIT);
	} else {
		k_work_reschedule(&client_data.cmd_timeout_work,
				  K_MSEC(min_timeout - current_time));
	}
}

static void smp_client_handle_Timer(struct k_work *work)
{
	int64_t current_time;
	smp_client_res_fn cb;
	void *user_data;

	k_mutex_lock(&client_data.lock, K_FOREVER);
	current_time = k_uptime_get();
	for (int i = 0; i < CONFIG_MCUMGR_SMP_CLIENT_MAX_CONCURRENT_REQUEST; i++) {
		if (client_data.cmd_list[i].nb &&
		    client_data.cmd_list[i].timeout <= current_time) {
			/* Free buffer */
			smp_client_buf_free(client_data.cmd_list[i].nb);
			client_data.cmd_list[i].nb = NULL;
			cb = client_data.cmd_list[i].cb;
			user_data = client_data.cmd_list[i].user_data;
			k_mutex_unlock(&client_data.lock);
			if (cb) {
				cb(NULL, user_data);
			}
			k_mutex_lock(&client_data.lock, K_FOREVER);
		}
	}

	smp_client_timeout_reschedule();
	k_mutex_unlock(&client_data.lock);
}

static struct smp_client_cmd_entry *smp_client_Entry_allocate(void)
{
	for (int i = 0; i < CONFIG_MCUMGR_SMP_CLIENT_MAX_CONCURRENT_REQUEST; i++) {
		if (client_data.cmd_list[i].nb == NULL) {
			return &client_data.cmd_list[i];
		}
	}

	return NULL;
}

int smp_client_single_response(struct net_buf *nb, const struct smp_hdr *res_hdr)
{
	smp_client_res_fn cb = NULL;
	void *user_data = NULL;
	struct smp_hdr *cmd_hdr;

	k_mutex_lock(&client_data.lock, K_FOREVER);

	for (int i = 0; i < CONFIG_MCUMGR_SMP_CLIENT_MAX_CONCURRENT_REQUEST; i++) {
		if (client_data.cmd_list[i].nb) {
			cmd_hdr = (struct smp_hdr *)client_data.cmd_list[i].nb->data;
			if (cmd_hdr->nh_seq == res_hdr->nh_seq &&
			    cmd_hdr->nh_id == res_hdr->nh_id &&
			    cmd_hdr->nh_group == res_hdr->nh_group) {
				if ((cmd_hdr->nh_op == MGMT_OP_READ &&
				     res_hdr->nh_op == MGMT_OP_READ_RSP) ||
				    (cmd_hdr->nh_op == MGMT_OP_WRITE &&
				     res_hdr->nh_op == MGMT_OP_WRITE_RSP)) {
					/* Free command buffer */
					smp_client_buf_free(client_data.cmd_list[i].nb);
					client_data.cmd_list[i].nb = NULL;
					cb = client_data.cmd_list[i].cb;
					user_data = client_data.cmd_list[i].user_data;
					break;
				}
			}
		}
	}

	if (cb) {
		smp_client_timeout_reschedule();
		k_mutex_unlock(&client_data.lock);
		cb(nb, user_data);
	} else {
		k_mutex_unlock(&client_data.lock);
	}

	smp_client_buf_free(nb);

	return MGMT_ERR_EOK;
}

int smp_client_send_cmd(struct smp_client_object *smp_client, struct net_buf *nb,
			smp_client_res_fn cb, void *user_data, int timeout_in_sec)
{
	struct smp_client_cmd_entry *cmd_entry;
	struct smp_hdr *uhdr;
	int rc;

	if (nb->len < sizeof(*uhdr)) {
		LOG_ERR("Drop invalid packet before sending.");
		return MGMT_ERR_EINVAL;
	}

	k_mutex_lock(&client_data.lock, K_FOREVER);
	cmd_entry = smp_client_Entry_allocate();
	if (!cmd_entry) {
		k_mutex_unlock(&client_data.lock);
		return MGMT_ERR_ENOMEM;
	}
	/* Give sequence number and set length */
	uhdr = (struct smp_hdr *)nb->data;
	uhdr->nh_seq = client_data.smp_seq++;
	uhdr->nh_len = sys_cpu_to_be16(nb->len - sizeof(*uhdr));

	rc = smp_client->smpt->functions.output(nb);
	if (rc) {
		k_mutex_unlock(&client_data.lock);
		return rc;
	}

	cmd_entry->nb = nb;
	cmd_entry->cb = cb;
	cmd_entry->user_data = user_data;
	cmd_entry->timeout = k_uptime_get() + ((int64_t)timeout_in_sec * 1000);

	smp_client_timeout_reschedule();
	k_mutex_unlock(&client_data.lock);

	return MGMT_ERR_EOK;
}

static int smp_client_init(void)
{
	k_mutex_init(&client_data.lock);
	for (int i = 0; i < CONFIG_MCUMGR_SMP_CLIENT_MAX_CONCURRENT_REQUEST; i++) {
		client_data.cmd_list[i].nb = NULL;
	}
	k_work_init_delayable(&client_data.cmd_timeout_work, smp_client_handle_Timer);
	client_data.smp_seq = 0;
	return 0;
}

SYS_INIT(smp_client_init, APPLICATION, CONFIG_APPLICATION_INIT_PRIORITY);
